const cfg = $('Config').first().json;
const crypto = require('crypto');
function rows(name) {
  return $(name).all().map(function (i) { return i.json; }).filter(function (j) { return j && Object.keys(j).length > 0 && !j.error; });
}
function P(x) {
  if (typeof x === 'string') { try { return JSON.parse(x); } catch (e) { return null; } }
  return x === undefined ? null : x;
}
function norm(s) { return typeof s === 'string' ? s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() : ''; }
function rate(n, d) { return d > 0 ? Math.round(n / d * 1000) / 1000 : null; }
function mode(arr) {
  const c = {}; let best = null;
  arr.forEach(function (x) { if (x === null || x === undefined) return; c[x] = (c[x] || 0) + 1; if (best === null || c[x] > c[best]) best = x; });
  return best;
}
function uniq(arr) { return arr.filter(function (x, i) { return x !== null && x !== undefined && arr.indexOf(x) === i; }); }

const allA = rows('Get Assessments');
const expertFb = rows('Get Expert-Verified Feedback');
const farmerFb = rows('Get Farmer-Reported Feedback');
const ruleRows = rows('Get Risk Rule Versions');
const pStart = Date.parse(cfg.periodStart);
const inPeriod = allA.filter(function (a) { return Date.parse(a.created_at) >= pStart; });
const amap = {};
allA.forEach(function (a) { amap[a.id] = a; });
const MIN_V = cfg.minVerifiedForConclusive;
const MIN_D = cfg.minPerDisease;
const MIN_R = cfg.minRecurring;
const MIN_P = cfg.minForProposal;

// ---------- Section 2: quality checks on the system's own outputs ----------
const CHECKS = ['required_response_fields', 'risk_score_gating', 'model_and_source_recorded', 'intervention_evidence', 'uncertain_diagnosis_gating', 'advisory_version_agreement', 'error_or_partial_marked'];
const stats = {};
CHECKS.forEach(function (c) { stats[c] = { evaluated: 0, failed: 0, sampleAssessmentIds: [] }; });
const failures = [];
function evalChecks(a) {
  const d = P(a.diagnosis), w = P(a.weather), r = P(a.risk_assessment), adv = P(a.advisory);
  let codes = P(a.error_codes);
  if (!Array.isArray(codes)) codes = [];
  const st = a.status;
  const res = {};
  function mark(id, reasons) { res[id] = reasons; }
  const ageMin = (Date.now() - Date.parse(a.created_at)) / 60000;
  if (!(st === 'completed' || st === 'partial' || st === 'failed')) {
    if (ageMin > 30) mark('error_or_partial_marked', ['Assessment stuck in status "' + st + '" for over 30 minutes; never reached a terminal status.']);
    return res;
  }
  const scoreIssued = !!(r && r.score !== null && r.score !== undefined);
  if (st !== 'failed') {
    const miss = [];
    if (!d) miss.push('diagnosis'); else if (!d.status) miss.push('diagnosis.status');
    if (!w) miss.push('weather'); else if (!w.status) miss.push('weather.status');
    if (!r) miss.push('riskAssessment'); else if (!r.status) miss.push('riskAssessment.status');
    if (!adv) miss.push('advisory'); else { if (!adv.level) miss.push('advisory.level'); if (!adv.summary) miss.push('advisory.summary'); if (!adv.disclaimer) miss.push('advisory.disclaimer'); }
    mark('required_response_fields', miss.length ? ['Missing required fields: ' + miss.join(', ')] : []);
  }
  if (r) {
    const rs = [];
    if (scoreIssued) {
      if (r.status !== 'calculated') rs.push('Score issued while risk status is "' + r.status + '".');
      if (!d || !Array.isArray(d.candidates) || d.candidates.length === 0) rs.push('Score issued without a disease candidate.');
      if (!w || w.status !== 'ok') rs.push('Score issued without a complete forecast (weather status: ' + (w ? w.status : 'missing') + ').');
      if (Array.isArray(r.missingInputs) && r.missingInputs.length > 0) rs.push('Score issued although missing inputs were listed.');
    }
    mark('risk_score_gating', rs);
  }
  if (st !== 'failed') {
    const rs = [];
    if (!a.risk_rule_version) rs.push('risk_rule_version not recorded.');
    if (!a.model_name) rs.push('model_name not recorded.');
    if (scoreIssued || (r && r.status === 'calculated')) {
      if (!r.model || !r.model.name || !r.model.version) rs.push('Risk model name/version not recorded for a calculated risk.');
      if (!Array.isArray(r.sourceUrls) || r.sourceUrls.length === 0) rs.push('No source references recorded for a calculated risk.');
    }
    mark('model_and_source_recorded', rs);
  }
  if (adv) {
    const rs = [];
    if (adv.level === 'verified_intervention') {
      if (!Array.isArray(adv.sourceReferences) || adv.sourceReferences.length === 0) rs.push('Intervention recommended without source references.');
      if (!r || !r.supportedInterventionWindow) rs.push('Intervention recommended without a supported intervention window.');
      if (!adv.evidence || adv.evidence.diseaseModelAvailable !== true) rs.push('Intervention recommended without a disease-specific model.');
      if (!adv.evidence || adv.evidence.forecastSufficient !== true) rs.push('Intervention recommended without a sufficient forecast.');
    }
    if (adv.chemicalRecommendation && (!Array.isArray(adv.sourceReferences) || adv.sourceReferences.length === 0)) rs.push('Chemical recommendation present without source references.');
    mark('intervention_evidence', rs);
  }
  if (d && adv) {
    const q = d.imageQuality ? d.imageQuality.rating : null;
    const uncertain = d.status === 'inconclusive' || d.status === 'failed' || q === 'poor' || q === 'unusable' || d.cropMatchesSelection === false;
    const rs = [];
    if (uncertain) {
      if (adv.level === 'verified_intervention') rs.push('Uncertain diagnosis was not gated: advisory level is verified_intervention.');
      if (scoreIssued) rs.push('Uncertain diagnosis was not gated: a risk score was issued.');
      if (d.status === 'candidate_identified' && (q === 'poor' || q === 'unusable' || d.cropMatchesSelection === false)) rs.push('Low-quality or crop-mismatched image still marked candidate_identified.');
    }
    mark('uncertain_diagnosis_gating', rs);
  }
  {
    const rs = [];
    if (r && r.riskRuleVersion !== undefined && (a.risk_rule_version || null) !== (r.riskRuleVersion || null)) rs.push('Stored risk_rule_version differs from the version inside the risk assessment.');
    if (d && d.model && (a.model_name || null) !== (d.model.name || null)) rs.push('Stored model_name differs from the diagnosis model.');
    if (r && r.model && (a.model_version || null) !== (r.model.version || null)) rs.push('Stored model_version differs from the risk model version.');
    if (st !== 'failed' || r) mark('advisory_version_agreement', rs);
  }
  {
    const rs = [];
    const dFailed = !!(d && d.status === 'failed');
    const wBad = !!(w && (w.status === 'unavailable' || w.status === 'partial'));
    const signal = dFailed || wBad;
    if (signal && st === 'completed') rs.push('Marked completed although a component failed or returned partial data.');
    if ((signal || st === 'partial' || st === 'failed') && codes.length === 0) rs.push('Partial/failed result has no error codes recorded.');
    if (!signal && st === 'completed' && codes.length > 0) rs.push('Completed result carries error codes: ' + codes.join(', '));
    mark('error_or_partial_marked', rs);
  }
  return res;
}
inPeriod.forEach(function (a) {
  const res = evalChecks(a);
  Object.keys(res).forEach(function (id) {
    stats[id].evaluated++;
    if (res[id].length > 0) {
      stats[id].failed++;
      if (stats[id].sampleAssessmentIds.length < 5) stats[id].sampleAssessmentIds.push(a.id);
      res[id].forEach(function (reason) { failures.push({ assessment_id: a.id, check: id, category: 'technical_failure', reason: reason }); });
    }
  });
});
const qualityChecks = {};
CHECKS.forEach(function (c) {
  qualityChecks[c] = { evaluated: stats[c].evaluated, failed: stats[c].failed, passRate: rate(stats[c].evaluated - stats[c].failed, stats[c].evaluated), sampleAssessmentIds: stats[c].sampleAssessmentIds };
});
const failureReasonCounts = {};
failures.forEach(function (f) { const k = f.check + ' :: ' + f.reason; failureReasonCounts[k] = (failureReasonCounts[k] || 0) + 1; });
const failureSummary = Object.keys(failureReasonCounts).map(function (k) { return { reason: k, count: failureReasonCounts[k] }; }).sort(function (x, y) { return y.count - x.count; }).slice(0, 25);

// ---------- Coverage ----------
let defensibleDx = 0, riskCalc = 0, abstainDx = 0, failedDx = 0;
const missingVarCounts = {};
inPeriod.forEach(function (a) {
  const d = P(a.diagnosis), w = P(a.weather), r = P(a.risk_assessment);
  const q = d && d.imageQuality ? d.imageQuality.rating : null;
  if (d && (d.status === 'candidate_identified' || d.status === 'no_visible_symptoms') && q !== 'poor' && q !== 'unusable') defensibleDx++;
  else if (d && d.status === 'failed') failedDx++;
  else abstainDx++;
  if (r && r.status === 'calculated') riskCalc++;
  if (w && Array.isArray(w.missingVariables)) w.missingVariables.forEach(function (v) { missingVarCounts[v] = (missingVarCounts[v] || 0) + 1; });
  if (w && Array.isArray(w.variablesWithGaps)) w.variablesWithGaps.forEach(function (v) { missingVarCounts[v + ' (gaps)'] = (missingVarCounts[v + ' (gaps)'] || 0) + 1; });
});
const coverage = {
  n: inPeriod.length,
  diagnosticCoverage: rate(defensibleDx, inPeriod.length),
  diagnosticDefensible: defensibleDx,
  diagnosticAbstained: abstainDx,
  diagnosticTechnicalFailures: failedDx,
  riskAssessmentCoverage: rate(riskCalc, inPeriod.length),
  riskCalculated: riskCalc,
  riskAbstainedOrUnavailable: inPeriod.length - riskCalc
};

// ---------- Section 3: formal evaluation, expert-verified only ----------
const latestByAssessment = {};
const conflicts = {};
expertFb.forEach(function (fb) {
  const prev = latestByAssessment[fb.assessment_id];
  if (!prev) { latestByAssessment[fb.assessment_id] = fb; return; }
  const sameLabel = prev.disease_observed === fb.disease_observed && norm(prev.confirmed_disease) === norm(fb.confirmed_disease);
  if (!sameLabel) conflicts[fb.assessment_id] = true;
  if (Date.parse(fb.created_at) > Date.parse(prev.created_at)) latestByAssessment[fb.assessment_id] = fb;
});
const excluded = { notEligibleFlag: 0, assessmentNotFound: 0, labelUnknown: 0, conflictingExpertLabels: 0, diagnosisTechnicalFailure: 0 };
const cases = [];
Object.keys(latestByAssessment).forEach(function (id) {
  const fb = latestByAssessment[id];
  const a = amap[id];
  if (!a) { excluded.assessmentNotFound++; return; }
  if (conflicts[id]) { excluded.conflictingExpertLabels++; return; }
  if (fb.evaluation_eligible !== true) { excluded.notEligibleFlag++; return; }
  if (fb.disease_observed === 'unknown' || (fb.disease_observed === 'true' && !norm(fb.confirmed_disease))) { excluded.labelUnknown++; return; }
  const d = P(a.diagnosis), r = P(a.risk_assessment), adv = P(a.advisory), w = P(a.weather);
  const truth = fb.disease_observed === 'false' ? 'healthy' : norm(fb.confirmed_disease);
  let pred = null, outcome = null;
  if (!d || d.status === 'failed') { excluded.diagnosisTechnicalFailure++; return; }
  if (d.status === 'inconclusive') outcome = 'abstained';
  else if (d.status === 'no_visible_symptoms') { pred = 'healthy'; outcome = 'answered'; }
  else if (d.status === 'candidate_identified' && d.candidates && d.candidates.length) { pred = norm(d.candidates[0].name); outcome = 'answered'; }
  else outcome = 'abstained';
  const riskCalculated = !!(r && r.status === 'calculated');
  const predictedAlert = riskCalculated && (adv && adv.level === 'verified_intervention' || (r && (r.alertLevel === 'high' || r.alert === true)));
  let avgRh = null, avgT = null;
  if (w && Array.isArray(w.hourly) && w.hourly.length) {
    const rh = w.hourly.map(function (h) { return h.relativeHumidityPct; }).filter(function (x) { return typeof x === 'number'; });
    const tt = w.hourly.map(function (h) { return h.temperatureC; }).filter(function (x) { return typeof x === 'number'; });
    if (rh.length) avgRh = Math.round(rh.reduce(function (s, x) { return s + x; }, 0) / rh.length * 10) / 10;
    if (tt.length) avgT = Math.round(tt.reduce(function (s, x) { return s + x; }, 0) / tt.length * 10) / 10;
  }
  cases.push({
    assessmentId: id, crop: norm(a.crop_type), observedCrop: norm(fb.observed_crop_type), truth: truth, pred: pred, outcome: outcome,
    version: (a.model_name || 'unknown') + ' | ' + (a.model_version || 'no-risk-model') + ' | ' + (a.risk_rule_version || 'unknown'),
    cropFlaggedByModel: !!(d && d.cropMatchesSelection === false),
    riskCalculated: riskCalculated, predictedAlert: !!predictedAlert, daysAfter: fb.days_after_assessment === undefined ? null : fb.days_after_assessment,
    diseaseObserved: fb.disease_observed, avgRh: avgRh, avgT: avgT
  });
});
const answered = cases.filter(function (c) { return c.outcome === 'answered'; });
const correct = answered.filter(function (c) { return c.pred === c.truth; });
const labelSet = uniq(cases.map(function (c) { return c.truth; }).concat(answered.map(function (c) { return c.pred; })));
const perDisease = labelSet.map(function (lab) {
  const tp = answered.filter(function (c) { return c.pred === lab && c.truth === lab; }).length;
  const fp = answered.filter(function (c) { return c.pred === lab && c.truth !== lab; }).length;
  const fn = cases.filter(function (c) { return c.truth === lab && (c.outcome === 'abstained' || c.pred !== lab); }).length;
  const support = cases.filter(function (c) { return c.truth === lab; }).length;
  return {
    label: lab, crops: uniq(cases.filter(function (c) { return c.truth === lab; }).map(function (c) { return c.crop; })),
    verifiedSupport: support, predictedCount: tp + fp, truePositive: tp, falsePositive: fp, falseNegativeIncludingAbstained: fn,
    precision: rate(tp, tp + fp), recall: rate(tp, tp + fn), status: support >= MIN_D ? 'reportable' : 'inconclusive_small_sample'
  };
}).sort(function (x, y) { return y.verifiedSupport - x.verifiedSupport; });
const versionKeys = uniq(cases.map(function (c) { return c.version; }));
const byVersion = versionKeys.map(function (v) {
  const cs = cases.filter(function (c) { return c.version === v; });
  const an = cs.filter(function (c) { return c.outcome === 'answered'; });
  const ok = an.filter(function (c) { return c.pred === c.truth; }).length;
  return { version: v, verifiedCases: cs.length, answered: an.length, abstained: cs.length - an.length, accuracy: rate(ok, an.length), status: an.length >= MIN_V ? 'reportable' : 'inconclusive_small_sample' };
});
const cropKeys = uniq(cases.map(function (c) { return c.crop; }));
const perCrop = cropKeys.map(function (cr) {
  const cs = cases.filter(function (c) { return c.crop === cr; });
  const an = cs.filter(function (c) { return c.outcome === 'answered'; });
  return { crop: cr, verifiedCases: cs.length, answered: an.length, abstained: cs.length - an.length, accuracy: rate(an.filter(function (c) { return c.pred === c.truth; }).length, an.length), status: an.length >= MIN_D ? 'reportable' : 'inconclusive_small_sample' };
});
const diagnostic = {
  status: cases.length === 0 ? 'insufficient_data' : (cases.length < MIN_V ? 'inconclusive' : 'reportable'),
  eligibleVerifiedExamples: cases.length, answered: answered.length, abstained: cases.length - answered.length,
  accuracyOnAnswered: rate(correct.length, answered.length), coverageOnVerified: rate(answered.length, cases.length),
  minVerifiedForConclusive: MIN_V, perDisease: perDisease, perCrop: perCrop, byModelAndRuleVersion: byVersion,
  note: 'Top-1 candidate name vs expert-confirmed disease (normalized text match). Abstentions count as missed for recall, not as errors for accuracy.'
};

// Temporal alert evaluation (only for cases where a risk timeline was actually calculated)
const EV = cfg.eventWindowDays;
const alertCases = cases.filter(function (c) { return c.riskCalculated; });
let aTP = 0, aFP = 0, aFN = 0, aTN = 0, aExcluded = 0;
alertCases.forEach(function (c) {
  const event = c.truth !== 'healthy';
  if (event && c.daysAfter !== null && c.daysAfter > EV) { aExcluded++; return; }
  if (!event && (c.daysAfter === null || c.daysAfter < EV)) { aExcluded++; return; }
  if (c.predictedAlert && event) aTP++; else if (c.predictedAlert && !event) aFP++; else if (!c.predictedAlert && event) aFN++; else aTN++;
});
const eventCases = cases.filter(function (c) { return c.truth !== 'healthy'; });
const eventNoCalc = eventCases.filter(function (c) { return !c.riskCalculated; }).length;
const alertN = aTP + aFP + aFN + aTN;
const alerts = {
  status: alertCases.length === 0 ? 'insufficient_data' : (alertN < MIN_V ? 'inconclusive' : 'reportable'),
  eventWindowDays: EV, verifiedCasesWithCalculatedRisk: alertCases.length, usableForAlertMetrics: alertN, excludedForTimingOrFollowUp: aExcluded,
  truePositive: aTP, falsePositive: aFP, missedEvents: aFN, trueNegative: aTN,
  precision: rate(aTP, aTP + aFP), recall: rate(aTP, aTP + aFN),
  observedDiseaseEventsWithNoCalculatedRisk: eventNoCalc, verifiedEventsTotal: eventCases.length,
  note: 'Alert = verified_intervention advisory or an explicit high alert flag on a calculated risk. Cases where no risk was calculated are reported as abstentions, never as correct non-alerts.'
};
const calibration = { computed: false, reason: 'The risk output is an environmental-suitability index, not a calibrated outbreak probability. No calibration metric (Brier, reliability) is computed.' };

// ---------- Farmer-reported (secondary, unverified) ----------
const outcomeCounts = {}, reportedDiseases = {};
let helpfulYes = 0, helpfulNo = 0;
farmerFb.forEach(function (f) {
  outcomeCounts[f.outcome_status] = (outcomeCounts[f.outcome_status] || 0) + 1;
  if (f.confirmed_disease) { const k = norm(f.confirmed_disease); reportedDiseases[k] = (reportedDiseases[k] || 0) + 1; }
  if (f.farmer_found_advisory_helpful === true) helpfulYes++;
  if (f.farmer_found_advisory_helpful === false) helpfulNo++;
});
const farmerReported = {
  verificationStatus: 'unverified_farmer_report', usedForFormalMetrics: false, n: farmerFb.length,
  outcomeStatusCounts: outcomeCounts, reportedDiseaseCounts: reportedDiseases, advisoryHelpful: { yes: helpfulYes, no: helpfulNo, notAnswered: farmerFb.length - helpfulYes - helpfulNo },
  note: 'Qualitative only. Not ground truth and never mixed into expert-verified metrics.'
};

// ---------- Section 4: systematic weaknesses ----------
const weaknesses = [];
function add(type, category, subject, count, n, note) { weaknesses.push({ type: type, category: category, subject: subject, count: count, n: n, recurring: count >= MIN_R, note: note }); }
CHECKS.forEach(function (c) { if (stats[c].failed > 0) add('repeated_quality_check_failure', 'technical_failure', c, stats[c].failed, stats[c].evaluated, 'Deterministic quality check failed on stored assessments.'); });
Object.keys(missingVarCounts).forEach(function (v) { add('missing_forecast_variable', 'technical_failure', v, missingVarCounts[v], inPeriod.length, 'Forecast variable missing or with gaps.'); });
const inconclusiveByCrop = {};
inPeriod.forEach(function (a) { const d = P(a.diagnosis); if (d && d.status === 'inconclusive') { const k = norm(a.crop_type) || 'unknown'; inconclusiveByCrop[k] = (inconclusiveByCrop[k] || 0) + 1; } });
Object.keys(inconclusiveByCrop).forEach(function (k) { add('repeated_inconclusive_image_assessment', 'uncertain_label', k, inconclusiveByCrop[k], inPeriod.length, 'Image assessments repeatedly inconclusive for this crop (diagnosis abstention, not necessarily an error).'); });
const cropMis = {};
cases.forEach(function (c) { if (c.observedCrop && c.observedCrop !== c.crop) { const k = c.crop + ' -> ' + c.observedCrop; cropMis[k] = (cropMis[k] || 0) + 1; } });
Object.keys(cropMis).forEach(function (k) { add('crop_misidentified', 'diagnostic_error', k, cropMis[k], cases.length, 'Expert-observed crop differs from the crop used in the assessment.'); });
const flaggedMismatch = cases.filter(function (c) { return c.cropFlaggedByModel; }).length;
if (flaggedMismatch > 0) add('model_flagged_crop_mismatch', 'uncertain_label', 'all crops', flaggedMismatch, cases.length, 'Model said the photographed plant may not match the selected crop.');
if (alerts.falsePositive > 0) add('high_risk_alert_not_confirmed', 'risk_model_error', 'alerts', alerts.falsePositive, alerts.usableForAlertMetrics, 'Alerts not followed by expert-confirmed disease within the event window.');
if (alerts.missedEvents > 0) add('disease_event_without_warning', 'risk_model_error', 'alerts', alerts.missedEvents, alerts.usableForAlertMetrics, 'Expert-confirmed disease events with a calculated risk but no alert.');
if (eventNoCalc > 0) add('disease_event_without_calculated_risk', 'risk_model_error', 'no risk model', eventNoCalc, eventCases.length, 'Verified disease events where the system had no calculated risk (abstained).');
perDisease.forEach(function (p) {
  if (p.label !== 'healthy' && p.verifiedSupport < MIN_D) add('insufficient_verified_data', 'uncertain_label', p.label, p.verifiedSupport, cases.length, 'Fewer than ' + MIN_D + ' verified cases; metrics are inconclusive.');
  if (p.label !== 'healthy' && p.verifiedSupport >= MIN_D && p.recall !== null && p.recall < 0.5) add('low_recall_disease', 'diagnostic_error', p.label, p.falseNegativeIncludingAbstained, p.verifiedSupport, 'Recall below 0.5 with an adequate sample.');
  if (p.label !== 'healthy' && p.verifiedSupport >= MIN_D && p.precision !== null && p.precision < 0.5) add('low_precision_disease', 'diagnostic_error', p.label, p.falsePositive, p.predictedCount, 'Precision below 0.5 with an adequate sample.');
});
if (excluded.labelUnknown > 0) add('unknown_expert_labels', 'uncertain_label', 'expert feedback', excluded.labelUnknown, expertFb.length, 'Expert feedback with unknown outcome excluded from metrics.');
if (excluded.conflictingExpertLabels > 0) add('conflicting_expert_labels', 'uncertain_label', 'expert feedback', excluded.conflictingExpertLabels, expertFb.length, 'Assessments with conflicting expert labels excluded.');

// ---------- Section 6: similar verified cases for context ----------
function similar(crop, disease) {
  return cases.filter(function (c) { return c.crop === crop && (c.truth === disease || c.pred === disease); }).slice(0, 3).map(function (c) {
    return { assessmentId: c.assessmentId, crop: c.crop, expertLabel: c.truth, systemLabel: c.outcome === 'answered' ? c.pred : 'abstained', ruleVersion: c.version, avgRelativeHumidityPct: c.avgRh, avgTemperatureC: c.avgT };
  });
}

// ---------- Run identity, versions, limitations, status ----------
const periodStartDay = String(cfg.periodStart).slice(0, 10);
const periodEndDay = String(cfg.periodEnd).slice(0, 10);
const ids = inPeriod.map(function (a) { return a.id; }).sort();
const fids = expertFb.concat(farmerFb).map(function (f) { return f.id; }).sort();
const runKey = 'eval-' + crypto.createHash('sha256').update(JSON.stringify([periodStartDay, periodEndDay, ids, fids, ruleRows.map(function (r) { return r.id || r.version; }).sort()])).digest('hex').slice(0, 32);
const modelVersionStr = uniq(inPeriod.map(function (a) { return (a.model_name || 'unknown') + '/' + (a.model_version || 'none'); })).slice(0, 5).join(', ') || 'none';
const ruleVersions = uniq(inPeriod.map(function (a) { return a.risk_rule_version; }));
const ruleVersionStr = ruleVersions.join(', ') || 'none';
const limitations = [
  'Only expert-verified feedback is used for formal metrics; farmer reports are secondary and unverified.',
  'Risk output is an environmental-suitability index, not a calibrated probability; no calibration was computed.',
  'Results describe past system outputs. No model parameters were retrained and no live rule was changed.',
  'Expert-verified cases may be biased towards cases that were severe, suspicious or easy to reach for experts.',
  'Disease matching uses normalized text of disease names; synonyms may be counted as errors.',
  'Data was bounded to ' + cfg.maxRows + ' rows per query; truncation is recorded in sampleSizes.'
];
const trunc = { assessments: allA.length >= cfg.maxRows, expertFeedback: expertFb.length >= cfg.maxRows, farmerFeedback: farmerFb.length >= cfg.maxRows };
if (trunc.assessments || trunc.expertFeedback || trunc.farmerFeedback) limitations.push('At least one query hit the row cap, so the dataset may be incomplete.');
if (cases.length === 0) limitations.push('No eligible expert-verified outcomes exist, so no predictive-performance metric was computed.');
else if (cases.length < MIN_V) limitations.push('Fewer than ' + MIN_V + ' verified examples: predictive metrics are inconclusive.');
const evaluationStatus = cases.length === 0 ? 'insufficient_data' : (cases.length < MIN_V ? 'inconclusive' : 'completed');

const metrics = {
  schemaVersion: 1, runKey: runKey, evaluatedAt: new Date().toISOString(),
  config: { windowDays: cfg.windowDays, eventWindowDays: EV, minVerifiedForConclusive: MIN_V, minPerDisease: MIN_D, minRecurring: MIN_R, minForProposal: MIN_P },
  sampleSizes: {
    assessmentsInPeriod: inPeriod.length, assessmentsLoadedIncludingLookback: allA.length,
    expertVerifiedFeedbackRows: expertFb.length, formalEvaluationEligible: cases.length, excluded: excluded,
    farmerReportRows: farmerFb.length, truncatedAtRowCap: trunc,
    assessmentsInPeriodWithoutExpertLabel: inPeriod.filter(function (a) { return !latestByAssessment[a.id]; }).length
  },
  versions: { riskRuleVersionsSeen: ruleVersions, registeredRuleVersions: ruleRows.length },
  qualityChecks: qualityChecks, qualityFailureReasons: failureSummary, qualityFailuresTotal: failures.length,
  coverage: coverage, diagnostic: diagnostic, alerts: alerts, calibration: calibration, farmerReported: farmerReported, weaknesses: weaknesses
};

// ---------- Section 6: proposals (never activated) ----------
const existingVersions = ruleRows.map(function (r) { return r.version || r.version_name || r.id; });
const parent = mode(inPeriod.map(function (a) { return a.risk_rule_version; })) || null;
const srcUrls = uniq([].concat.apply([], inPeriod.map(function (a) { const r = P(a.risk_assessment); return r && Array.isArray(r.sourceUrls) ? r.sourceUrls : []; }))).slice(0, 10);
const proposals = [];
function propose(changeType, title, description, evidence) {
  const version = 'proposed-' + runKey.slice(5, 13) + '-' + (proposals.length + 1);
  if (existingVersions.indexOf(version) !== -1) return;
  proposals.push({
    version: version, status: 'proposed', parent_version: parent, change_type: changeType, title: title, description: description,
    evidence: evidence, source_references: ['evaluation_run:' + runKey].concat(srcUrls),
    requires_expert_review: true, regression_test_status: 'required_not_run', regression_test_result: null,
    evaluation_run_key: runKey, activated_at: null, created_by: 'agrisentry-evaluation-workflow'
  });
}
CHECKS.forEach(function (c) {
  if (stats[c].failed >= MIN_P) {
    propose('validation_or_prompt_review', 'Review validation for ' + c,
      'The deterministic check "' + c + '" failed ' + stats[c].failed + ' of ' + stats[c].evaluated + ' times. Review response validation or advisory gating logic; this is a workflow reliability issue, not evidence about disease biology.',
      { check: c, failed: stats[c].failed, evaluated: stats[c].evaluated, sampleAssessmentIds: stats[c].sampleAssessmentIds, topReasons: failureSummary.filter(function (f) { return f.reason.indexOf(c + ' ::') === 0; }).slice(0, 3) });
  }
});
if (alerts.status === 'reportable' && (alerts.falsePositive >= MIN_P || alerts.missedEvents >= MIN_P)) {
  const topDisease = eventCases.length ? eventCases[0].truth : null;
  propose('risk_rule_review', 'Review alert thresholds against verified outcomes',
    'Verified outcomes show ' + alerts.falsePositive + ' unconfirmed alerts and ' + alerts.missedEvents + ' missed events out of ' + alerts.usableForAlertMetrics + ' usable cases. An expert should review the disease-specific rule against its source methodology. Rules must not be changed from outcome counts alone.',
    { alerts: alerts, similarVerifiedCases: topDisease ? similar(eventCases[0].crop, topDisease) : [] });
}
if (diagnostic.status === 'reportable') {
  perDisease.forEach(function (p) {
    if (p.label !== 'healthy' && p.verifiedSupport >= MIN_D && ((p.recall !== null && p.recall < 0.5) || (p.precision !== null && p.precision < 0.5)) && proposals.length < 10) {
      propose('prompt_review', 'Review image-analysis prompt for ' + p.label,
        'With ' + p.verifiedSupport + ' verified cases, precision is ' + p.precision + ' and recall is ' + p.recall + ' for "' + p.label + '". Review the image-analysis prompt and candidate handling; do not alter the deterministic risk calculation.',
        { disease: p.label, metrics: p, similarVerifiedCases: similar(p.crops[0] || '', p.label) });
    }
  });
}

const runRow = {
  run_key: runKey, period_start: cfg.periodStart, period_end: cfg.periodEnd, dataset_size: inPeriod.length,
  expert_verified_size: expertFb.length, metrics: metrics, model_version: modelVersionStr, risk_rule_version: ruleVersionStr,
  limitations: limitations, evaluation_status: evaluationStatus, workflow_execution_id: String($execution.id), created_at: new Date().toISOString()
};
return [{ json: { runKey: runKey, runRow: runRow, proposals: proposals, failedChecks: failures.slice(0, 200) } }];
